for (var r : records) {
    try {
        handle(r);
    } catch (RetryableException e) {
        throw e;                   // 커밋하지 않고 다시 시도
    } catch (Exception e) {
        dlt.send(r, e);            // 못 고칠 것은 따로 모은다 (9.5절)
        failureCounter.increment(); // 지표로 뽑아 알람
    }
}
